  --sidebar: hsl(0, 0%, 100%);
  --sidebar-foreground: hsl(210, 25%, 7.8%);
  --sidebar-primary: hsl(142, 69%, 48%);
  --sidebar-primary-foreground: hsl(0, 0%, 100%);
  --sidebar-accent: hsl(142, 76%, 94%);
  --sidebar-accent-foreground: hsl(142, 69%, 48%);
  --sidebar-border: hsl(214, 32%, 91%);
  --sidebar-ring: hsl(142, 69%, 48%);
