.dark {
  --background: hsl(222, 84%, 5%);
  --foreground: hsl(210, 40%, 98%);
  --card: hsl(222, 84%, 5%);
  --card-foreground: hsl(210, 40%, 98%);
  --popover: hsl(222, 84%, 5%);
  --popover-foreground: hsl(210, 40%, 98%);
  --primary: hsl(142, 69%, 48%);
  --primary-foreground: hsl(0, 0%, 100%);
  --secondary: hsl(217, 32%, 17%);
  --secondary-foreground: hsl(210, 40%, 98%);
  --muted: hsl(217, 32%, 17%);
  --muted-foreground: hsl(215, 20%, 65%);
  --accent: hsl(217, 32%, 17%);
  --accent-foreground: hsl(210, 40%, 98%);
  --destructive: hsl(0, 62%, 30%);
  --destructive-foreground: hsl(0, 0%, 100%);
  --border: hsl(217, 32%, 17%);
  --input: hsl(217, 32%, 17%);
  --ring: hsl(142, 69%, 48%);
  --chart-1: hsl(142, 69%, 48%);
  --chart-2: hsl(173, 58%, 39%);
  --chart-3: hsl(197, 37%, 24%);
  --chart-4: hsl(43, 74%, 66%);
  --chart-5: hsl(27, 87%, 67%);
  --sidebar: hsl(222, 84%, 5%);
  --sidebar-foreground: hsl(210, 40%, 98%);
  --sidebar-primary: hsl(142, 69%, 48%);
  --sidebar-primary-foreground: hsl(0, 0%, 100%);
  --sidebar-accent: hsl(217, 32%, 17%);
  --sidebar-accent-foreground: hsl(210, 40%, 98%);
  --sidebar-border: hsl(217, 32%, 17%);
  --sidebar-ring: hsl(142, 69%, 48%);
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen', 'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue', sans-serif;
  --font-serif: Georgia, serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', Consolas, 'Liberation Mono', Menlo, Courier, monospace;
  --radius: 0.5rem;
  --shadow-2xs: 0px 1px 2px 0px hsl(0, 0%, 0%, 0.05);
  --shadow-xs: 0px 1px 2px 0px hsl(0, 0%, 0%, 0.05);
  --shadow-sm: 0px 1px 3px 0px hsl(0, 0%, 0%, 0.1), 0px 1px 2px 0px hsl(0, 0%, 0%, 0.06);
  --shadow: 0px 1px 3px 0px hsl(0, 0%, 0%, 0.1), 0px 1px 2px 0px hsl(0, 0%, 0%, 0.06);
  --shadow-md: 0px 4px 6px -1px hsl(0, 0%, 0%, 0.1), 0px 2px 4px -1px hsl(0, 0%, 0%, 0.06);
  --shadow-lg: 0px 10px 15px -3px hsl(0, 0%, 0%, 0.1), 0px 4px 6px -2px hsl(0, 0%, 0%, 0.05);
  --shadow-xl: 0px 20px 25px -5px hsl(0, 0%, 0%, 0.1), 0px 10px 10px -5px hsl(0, 0%, 0%, 0.04);
  --shadow-2xl: 0px 25px 50px -12px hsl(0, 0%, 0%, 0.25);
}

@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply font-sans antialiased bg-background text-foreground;
    font-feature-settings: "rlig" 1, "calt" 1;
  }

  html {
    scroll-behavior: smooth;
  }
}

@layer utilities {
  .transition-theme {
    @apply transition-all duration-300 ease-in-out;
  }

  .sent-period {
    @apply bg-gray-200 dark:bg-gray-700 text-gray-500 dark:text-gray-400 pointer-events-none;
  }

  .quality-rating button.active {
    @apply bg-green-600 text-white;
  }

  .context-menu {
    @apply absolute bg-card border border-border rounded-lg py-2 shadow-lg z-50;
  }

  .context-menu button {
    @apply block w-full text-left px-4 py-2 text-sm hover:bg-accent hover:text-accent-foreground transition-colors;
  }

  /* Timesheet specific styles */
  .timesheet-cell-sick {
    @apply bg-blue-100 dark:bg-blue-900/20;
  }

  .timesheet-cell-vacation {
    @apply bg-purple-100 dark:bg-purple-900/20;
  }

  .timesheet-cell-absence {
    @apply bg-gray-100 dark:bg-gray-800;
  }

  .timesheet-cell-fired {
    @apply bg-red-100 dark:bg-red-900/20;
  }

  .timesheet-cell-quality-1 {
    @apply bg-red-100 dark:bg-red-900/20;
  }

  .timesheet-cell-quality-2 {
    @apply bg-orange-100 dark:bg-orange-900/20;
  }

  .timesheet-cell-quality-3 {
    @apply bg-yellow-100 dark:bg-yellow-900/20;
  }

  .timesheet-cell-quality-4 {
    @apply bg-green-100 dark:bg-green-900/20;
  }

  /* Weekend styling */
  .weekend-cell {
    @apply bg-red-50 dark:bg-red-900/20;
  }

  /* Status badges */
  .status-active {
    @apply bg-green-100 text-green-800 dark:bg-green-900/20 dark:text-green-400;
  }

  .status-part-time {
    @apply bg-orange-100 text-orange-800 dark:bg-orange-900/20 dark:text-orange-400;
  }

  .status-fired {
    @apply bg-red-100 text-red-800 dark:bg-red-900/20 dark:text-red-400;
  }

  .status-sent {
    @apply bg-green-100 text-green-800 dark:bg-green-900/20 dark:text-green-400;
  }

  .status-draft {
    @apply bg-orange-100 text-orange-800 dark:bg-orange-900/20 dark:text-orange-400;
  }

  /* Progress indicators */
  .progress-danger {
    @apply bg-red-500;
  }

  .progress-warning {
    @apply bg-orange-500;
  }

  .progress-success {
    @apply bg-green-500;
  }

  /* Focus improvements */
  .focus-visible {
    @apply focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2;
  }

  /* Scrollbar styling */
  .scrollbar-thin {
    scrollbar-width: thin;
    scrollbar-color: hsl(var(--muted-foreground)) transparent;
  }

  .scrollbar-thin::-webkit-scrollbar {
    width: 6px;
    height: 6px;
  }

  .scrollbar-thin::-webkit-scrollbar-track {
    background: transparent;
  }

  .scrollbar-thin::-webkit-scrollbar-thumb {
    background-color: hsl(var(--muted-foreground));
    border-radius: 3px;
  }

  .scrollbar-thin::-webkit-scrollbar-thumb:hover {
    background-color: hsl(var(--foreground));
  }
}

/* Animation keyframes */
@keyframes fade-in {
  from {
    opacity: 0;
    transform: translateY(-10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes slide-in-right {
  from {
    opacity: 0;
    transform: translateX(100%);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes pulse-green {
  0%, 100% {
    box-shadow: 0 0 0 0 hsl(var(--primary) / 0.7);
  }
  50% {
    box-shadow: 0 0 0 10px hsl(var(--primary) / 0);
  }
}

.animate-fade-in {
  animation: fade-in 0.3s ease-out;
}

.animate-slide-in-right {
  animation: slide-in-right 0.3s ease-out;
}

.animate-pulse-green {
  animation: pulse-green 2s infinite;
}

/* Print styles */
@media print {
  .no-print {
    display: none !important;
  }

  .print-break-after {
    page-break-after: always;
  }

  .print-break-before {
    page-break-before: always;
  }
}

/* High contrast mode support */
@media (prefers-contrast: high) {
  :root {
    --border: hsl(0, 0%, 0%);
    --ring: hsl(0, 0%, 0%);
  }

  .dark {
    --border: hsl(0, 0%, 100%);
    --ring: hsl(0, 0%, 100%);
  }
}

/* Reduced motion support */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

