  // Import staffing schedule from CSV
  app.post("/api/import/staffing", requireAuth, requireRole("economist"), upload.single("file"), async (req, res) => {
    if (!req.file) {
      return res.status(400).json({ message: "Файл не найден" });
    }

    try {
      const fileContent = req.file.buffer.toString('utf-8');
      const lines = fileContent.split('\n').filter(line => line.trim());

      if (lines.length === 0) {
        return res.status(400).json({ message: "Файл пуст" });
      }

      // Remove BOM if present and parse header
      const header = lines[0].replace(/^\uFEFF/, '').split(';');
      const dataLines = lines.slice(1);

      // Expected columns: Объект;Должность;График работы;Оклад (тариф);Количество ставок;Тип оплаты (или Тип оплат)
      const expectedColumns = ['Объект', 'Должность', 'График работы', 'Оклад (тариф)', 'Количество ставок'];
      const acceptableHeaders = [
        'Тип оплат', 'Тип оплаты', 'тип оплат', 'тип оплаты'
      ];

      if (header.length < 6) {
        return res.status(400).json({ 
          message: `Неправильный формат файла. Ожидается 6 колонок: ${expectedColumns.join(';')};Тип оплаты` 
        });
      }

      // Check if last column is a payment type column
      const lastColumn = header[5].trim();
      if (!acceptableHeaders.some(h => h.toLowerCase() === lastColumn.toLowerCase())) {
        return res.status(400).json({ 
          message: `Неправильный заголовок в 6-й колонке: "${lastColumn}". Ожидается "Тип оплаты" или "Тип оплат"` 
        });
      }

      const objects = await storage.getObjects();
      const objectMap = new Map();
      objects.forEach(obj => {
        objectMap.set(obj.name, obj.id);
      });

      const staffingData = new Map(); // objectId -> position -> { workSchedule, salary, count }
      let processedRows = 0;
      let skippedRows = 0;

      for (const line of dataLines) {
        const columns = line.split(';');
        if (columns.length < 6) continue;

        const [objectName, position, workSchedule, salaryStr, positionsCountStr, paymentTypeStr] = columns.map(col => col.trim());

        if (!objectName || !position || !salaryStr || !positionsCountStr || !paymentTypeStr) continue;

        const objectId = objectMap.get(objectName);
        if (!objectId) {
          console.warn(`Object not found: ${objectName}`);
          skippedRows++;
          continue;
        }

        // Parse salary (remove spaces, commas and convert to number)
        const cleanSalaryStr = salaryStr.replace(/\s/g, '').replace(/,/g, '').replace(/\./g, '');
        const salary = parseFloat(cleanSalaryStr);
        if (isNaN(salary) || salary < 0) {
          console.warn(`Invalid salary: ${salaryStr}`);
          skippedRows++;
          continue;
        }

        // Parse positions count (handle fractions like "1/2", "1/4")
        let positionsCount: number;
        const cleanCountStr = positionsCountStr.replace(/\s/g, '');

        if (cleanCountStr.includes('/')) {
          // Handle fractions like "1/2", "1/4"
          const [numerator, denominator] = cleanCountStr.split('/').map(n => parseInt(n));
          if (isNaN(numerator) || isNaN(denominator) || denominator === 0) {
            console.warn(`Invalid fractional positions count: ${positionsCountStr}`);
            skippedRows++;
            continue;
          }
          positionsCount = numerator / denominator;
        } else {
          positionsCount = parseInt(cleanCountStr);
          if (isNaN(positionsCount) || positionsCount < 0) {
            console.warn(`Invalid positions count: ${positionsCountStr}`);
            skippedRows++;
            continue;
          }
        }

        // Parse payment type - handle both "тариф"/"оклад" and "Почасовая"/"Оклад"
        const paymentTypeLower = paymentTypeStr.toLowerCase().trim();
        let paymentType: string;

        if (paymentTypeLower.includes('тариф') || paymentTypeLower.includes('почасовая')) {
          paymentType = 'hourly';
        } else if (paymentTypeLower.includes('оклад') || paymentTypeLower.includes('salary')) {
          paymentType = 'salary';
        } else {
          console.warn(`Unknown payment type: ${paymentTypeStr}, defaulting to salary`);
          paymentType = 'salary';
        }

        // Create unique position entry
        if (!staffingData.has(objectId)) {
          staffingData.set(objectId, new Map());
        }

        const objectPositions = staffingData.get(objectId);
        const positionKey = `${position}_${workSchedule}_${paymentType}_${salary}`;

        if (!objectPositions.has(positionKey)) {
          objectPositions.set(positionKey, {
            title: position,
            workSchedule: workSchedule || "5/2",
            salary: salary,
            paymentType: paymentType,
            count: positionsCount
          });
        } else {
          objectPositions.get(positionKey).count += positionsCount;
        }

        processedRows++;
      }

      // Create positions in database
      let createdPositions = 0;
      for (const [objectId, positions] of Array.from(staffingData.entries())) {
        for (const [, positionData] of Array.from((positions as Map<string, any>).entries())) {
          try {
            // Use the payment type from CSV data
            let hourlyRate = null;
            let monthlySalary = null;

            if (positionData.paymentType === "hourly") {
              hourlyRate = positionData.salary;
            } else {
              monthlySalary = positionData.salary;
            }

            await storage.createPosition({
              objectId,
              title: positionData.title,
              workSchedule: normalizeWorkSchedule(positionData.workSchedule) as "5/2" | "2/2" | "3/3" | "6/1" | "вахта",
              paymentType: positionData.paymentType as "hourly" | "salary",
              hoursPerShift: 8,
              hourlyRate: hourlyRate,
              monthlySalary: monthlySalary,
              positionsCount: positionData.count,
              isActive: true
            });
            createdPositions++;
          } catch (error) {
            console.error("Error creating position:", error);
          }
        }
      }

      res.json({ 
        message: "Импорт штатного расписания завершён успешно",
        processedRows,
        skippedRows,
        positionsCount: createdPositions
      });
    } catch (error) {
      console.error("Error importing staffing:", error);
      res.status(500).json({ message: "Ошибка при импорте файла" });
    }
  });

