import { useState, useMemo } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { TimesheetCell } from "@/components/timesheet/timesheet-cell";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";
import { format, getDaysInMonth, parseISO, isAfter } from "date-fns";
import { ru } from "date-fns/locale";
import { Wand2, Calendar, Lock, LockOpen, ChevronDown, ChevronRight } from "lucide-react";
import { Employee, TimeEntry, Position, TimesheetPeriod, Object as ObjectType, User } from "@shared/schema";
import { useObjectStore } from "@/lib/object-store";

// Type for timesheet row that can be either an employee or a vacancy
type TimesheetRow = {
  id: string;
  type: 'employee' | 'vacancy';
  employee?: Employee;
  position?: Position;
  name: string;
  positionTitle: string;
  status: string;
};

export default function Timesheet() {
  // Автоматически устанавливать текущий месяц
  const getCurrentMonth = () => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
  };

  const [selectedMonth, setSelectedMonth] = useState(getCurrentMonth());
  const [vacanciesExpanded, setVacanciesExpanded] = useState(false);

  const { toast } = useToast();
  const queryClient = useQueryClient();
  const { selectedObjectId } = useObjectStore();

  // Fetch objects to get manager information
  const { data: objects = [] } = useQuery<ObjectType[]>({
    queryKey: ["/api/objects"],
  });

  const { data: users = [] } = useQuery<User[]>({
    queryKey: ["/api/users"],
  });

  const currentObject = objects.find(obj => obj.id === selectedObjectId);
  const objectManager = users.find(u => u.id === currentObject?.managerId);
  const objectManagerName = objectManager?.name;

  const { data: employees = [] } = useQuery<Employee[]>({
    queryKey: ["/api/employees", selectedObjectId],
    queryFn: () => {
      const url = selectedObjectId ? `/api/employees?objectId=${selectedObjectId}` : '/api/employees';
      return fetch(url).then(res => res.json());
    },
  });

  const { data: timeEntries = [] } = useQuery<TimeEntry[]>({
    queryKey: ["/api/time-entries", selectedMonth],
    queryFn: async () => {
      const startDate = `${selectedMonth}-01`;
      const endDate = `${selectedMonth}-${getDaysInMonth(new Date(selectedMonth + "-01"))}`;
      const response = await fetch(`/api/time-entries?startDate=${startDate}&endDate=${endDate}`);
      return response.json();
    },
  });

  const { data: positions = [], isLoading: isPositionsLoading } = useQuery<Position[]>({
    queryKey: ["/api/positions", selectedObjectId],
    enabled: !!selectedObjectId,
    queryFn: () => fetch(`/api/positions?objectId=${selectedObjectId}`).then(r => r.json()),
  });

  // Get timesheet period status
  const { data: periodStatus } = useQuery<TimesheetPeriod | { status: string; reportStatus: string | null }>({
    queryKey: ["/api/timesheet-periods", selectedObjectId, selectedMonth],
    enabled: !!selectedObjectId,
  });

  const isPeriodClosed = periodStatus?.status === "closed";
  const isReportApproved = periodStatus?.reportStatus === "approved";

  const updateTimeEntryMutation = useMutation({
    mutationFn: async (data: any) => {
      if (data.id) {
        return await apiRequest("PUT", `/api/time-entries/${data.id}`, data);
      } else {
        return await apiRequest("POST", "/api/time-entries", data);
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/time-entries", selectedMonth] });
    },
    onError: () => {
      toast({ title: "Ошибка при сохранении данных", variant: "destructive" });
    },
  });

  const closePeriodMutation = useMutation({
    mutationFn: async () => {
      return await apiRequest("POST", `/api/timesheet-periods/${selectedObjectId}/${selectedMonth}/close`, {});
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/timesheet-periods", selectedObjectId, selectedMonth] });
      toast({ title: "Период закрыт", description: "Табель больше не доступен для редактирования" });
    },
    onError: () => {
      toast({ title: "Ошибка при закрытии периода", variant: "destructive" });
    },
  });

  const reopenPeriodMutation = useMutation({
    mutationFn: async () => {
      return await apiRequest("POST", `/api/timesheet-periods/${selectedObjectId}/${selectedMonth}/reopen`, {});
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/timesheet-periods", selectedObjectId, selectedMonth] });
      toast({ title: "Период открыт", description: "Табель снова доступен для редактирования" });
    },
    onError: (error: any) => {
      toast({ 
        title: "Ошибка при открытии периода", 
        description: error.message || "Невозможно открыть период",
        variant: "destructive" 
      });
    },
  });

  // Generate calendar data
  const year = parseInt(selectedMonth.split("-")[0]);
  const month = parseInt(selectedMonth.split("-")[1]);
  const daysInMonth = getDaysInMonth(new Date(year, month - 1));

  const days = Array.from({ length: daysInMonth }, (_, i) => {
    const day = i + 1;
    const date = new Date(year, month - 1, day);
    const dayOfWeek = date.getDay();
    const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;

    return {
      day,
      date: format(date, "yyyy-MM-dd"),
      dayOfWeek: format(date, "EEEEEE", { locale: ru }),
      isWeekend,
    };
  });

  // Create combined timesheet rows from employees and positions
  const createTimesheetRows = (): TimesheetRow[] => {
    const rows: TimesheetRow[] = [];

    // Filter visible employees
    const allVisibleEmployees = employees.filter((emp) => {
      if (emp.status === "active" || emp.status === "not_registered") {
        return true;
      }
      if (emp.status === "fired" && emp.terminationDate) {
        // Show fired employees if current month is same or before their termination month
        const terminationMonth = emp.terminationDate.substring(0, 7); // YYYY-MM format
        return selectedMonth <= terminationMonth;
      }
      return false;
    });

    // Add employees to rows
    allVisibleEmployees.forEach(emp => {
      rows.push({
        id: emp.id,
        type: 'employee',
        employee: emp,
        name: emp.name,
        positionTitle: emp.position || 'Не указано',
        status: emp.status,
      });
    });

    // Add vacancies for positions without assigned employees
    positions.forEach(position => {
      // Check if we need multiple vacancies for this position (positionsCount > 1)
      const assignedEmployeesCount = allVisibleEmployees.filter(emp => 
        emp.position === position.title && emp.objectId === position.objectId
      ).length;

      const vacanciesNeeded = Math.max(0, position.positionsCount - assignedEmployeesCount);

      for (let i = 0; i < vacanciesNeeded; i++) {
        rows.push({
          id: `vacancy-${position.id}-${i}`,
          type: 'vacancy',
          position,
          name: 'Вакансия',
          positionTitle: position.title,
          status: 'vacancy',
        });
      }
    });

    return rows;
  };

  const timesheetRows = createTimesheetRows();

  // Функция для группировки и сортировки сотрудников
  const groupActiveEmployeesWithReplacements = (rows: TimesheetRow[], managerName?: string): TimesheetRow[] => {
    // Фильтруем только активных и уволенных сотрудников
    const employeeRows = rows.filter(row => 
      row.type === 'employee' && (row.employee?.status === "active" || row.employee?.status === "fired")
    );

    // Категоризуем сотрудников
    const manager: TimesheetRow[] = [];
    const administrators: TimesheetRow[] = [];
    const regular: TimesheetRow[] = [];

    employeeRows.forEach(row => {
      // Проверяем, является ли сотрудник менеджером объекта (сравниваем по имени)
      if (managerName && row.employee?.name === managerName) {
        manager.push(row);
      }
      // Проверяем, является ли должность администратором
      else if (row.positionTitle.toLowerCase().includes('администратор')) {
        administrators.push(row);
      }
      // Все остальные
      else {
        regular.push(row);
      }
    });

    // Сортируем администраторов и обычных сотрудников по алфавиту
    const sortByName = (a: TimesheetRow, b: TimesheetRow) => a.name.localeCompare(b.name, 'ru');
    administrators.sort(sortByName);
    regular.sort(sortByName);

    // Объединяем: менеджер → администраторы → остальные
    const sortedEmployees = [...manager, ...administrators, ...regular];

    // Теперь применяем логику замен для отсортированного списка
    const result: TimesheetRow[] = [];
    const processed = new Set<string>();

    sortedEmployees.forEach(row => {
      if (processed.has(row.id)) return;

      // Если сотрудник уволен в текущем периоде
      if (row.employee?.status === "fired" && 
          row.employee?.terminationDate?.substring(0, 7) === selectedMonth) {
        result.push(row);
        processed.add(row.id);

        // Ищем замену: активного сотрудника на той же должности, принятого в том же месяце
        const replacement = sortedEmployees.find(otherRow => 
          !processed.has(otherRow.id) &&
          otherRow.employee?.status === "active" &&
          otherRow.positionTitle === row.positionTitle &&
          otherRow.employee?.hireDate?.substring(0, 7) === selectedMonth
        );

        if (replacement) {
          result.push(replacement);
          processed.add(replacement.id);
        }
      } 
      // Активные сотрудники
      else if (row.employee?.status === "active") {
        result.push(row);
        processed.add(row.id);
      }
    });

    // Добавляем уволенных вне периода в конец
    sortedEmployees.forEach(row => {
      if (!processed.has(row.id) && 
          row.employee?.status === "fired" && 
          row.employee?.terminationDate?.substring(0, 7) !== selectedMonth) {
        result.push(row);
      }
    });

    return result;
  };

  // Разделить на три секции: штатные сотрудники, подработчики, вакансии  
  const activeEmployeeRows = groupActiveEmployeesWithReplacements(timesheetRows, objectManagerName);

  const partTimeEmployeeRows = timesheetRows
    .filter(row => 
      row.type === 'employee' && row.employee?.status === "not_registered"
    )
    .sort((a, b) => {
      // Сортировка только по имени (ФИО)
      return a.name.localeCompare(b.name, 'ru');
    });

  const vacancyRows = timesheetRows
    .filter(row => row.type === 'vacancy')
    .sort((a, b) => {
      // Сортировка по должности, затем по номеру вакансии
      if (a.positionTitle !== b.positionTitle) {
        return a.positionTitle.localeCompare(b.positionTitle, 'ru');
      }
      // Извлекаем номер вакансии из id (vacancy-{positionId}-{index})
      const getVacancyNumber = (id: string) => {
        const parts = id.split('-');
        return parseInt(parts[parts.length - 1] || '0', 10);
      };
      return getVacancyNumber(a.id) - getVacancyNumber(b.id);
    });

  // Keep old variables for compatibility
  const activeEmployees = activeEmployeeRows.map(row => row.employee!);
  const partTimeEmployees = partTimeEmployeeRows.map(row => row.employee!);

  const getTimeEntry = (employeeId: string, date: string) => {
    return timeEntries.find((entry: TimeEntry) => 
      entry.employeeId === employeeId && entry.date === date
    );
  };

  const isEmployeeTerminated = (employee: Employee, date: string) => {
    if (employee.status !== "fired" || !employee.terminationDate) return false;
    const cellDate = parseISO(date);
    const terminationDate = parseISO(employee.terminationDate);
    return cellDate >= terminationDate;
  };

  const isBeforeHireDate = (employee: Employee, date: string) => {
    if (!employee.hireDate) return false;
    const cellDate = parseISO(date);
    const hireDate = parseISO(employee.hireDate);
    return cellDate < hireDate;
  };

  const isCellLocked = (date: string, employee?: Employee) => {
    // If period is closed, all cells are locked
    if (isPeriodClosed) return true;

    // Days before hire date are locked
    if (employee && isBeforeHireDate(employee, date)) return true;

    // Future dates are locked
    const cellDate = parseISO(date);
    const today = new Date();
    return isAfter(cellDate, today);
  };

  const isCellTerminated = (employee: Employee, date: string) => {
    return isEmployeeTerminated(employee, date);
  };

  // Calculate total hours for a group of employees
  const calculateGroupTotal = (employeeList: Employee[]) => {
    return employeeList.reduce((total, employee) => {
      const employeeTotal = timeEntries
        .filter((entry: TimeEntry) => entry.employeeId === employee.id && typeof entry.hours === 'number')
        .reduce((sum: number, entry: TimeEntry) => sum + (entry.hours || 0), 0);
      return total + employeeTotal;
    }, 0);
  };

  // Calculate planned hours for employee based on 5/2 schedule (8 hours per working day)
  const calculatePlannedHours = (employee: Employee) => {
    if (employee.status === 'fired' && employee.terminationDate) {
      // For fired employees, count only working days until termination
      const terminationDate = parseISO(employee.terminationDate);
      const workingDays = days.filter(day => {
        const dayDate = parseISO(day.date);
        return !day.isWeekend && !isAfter(dayDate, terminationDate);
      }).length;
      return workingDays * 8;
    } else {
      // For active employees, count all working days in month
      const workingDays = days.filter(day => !day.isWeekend).length;
      return workingDays * 8;
    }
  };

  // Check if employee has insufficient hours (less than planned)
  const hasInsufficientHours = (employee: Employee, actualHours: number) => {
    const plannedHours = calculatePlannedHours(employee);
    return actualHours < plannedHours;
  };

  // Optimize timeEntries lookup with memoized index
  const timeEntriesMap = useMemo(() => {
    const map = new Map<string, TimeEntry[]>();
    timeEntries.forEach((entry: TimeEntry) => {
      if (!map.has(entry.employeeId)) {
        map.set(entry.employeeId, []);
      }
      map.get(entry.employeeId)!.push(entry);
    });
    return map;
  }, [timeEntries]);

  // Helper functions for TimesheetRow
  const getRowTotalHours = (row: TimesheetRow): number => {
    if (row.type === 'vacancy') return 0;
    const entries = timeEntriesMap.get(row.id) || [];
    return entries
      .filter((entry: TimeEntry) => 
        typeof entry.hours === 'number' && 
        entry.hours >= 0 && 
        entry.hours <= 24
      )
      .reduce((sum: number, entry: TimeEntry) => sum + (entry.hours || 0), 0);
  };

  const getRowPlannedHours = (row: TimesheetRow): number => {
    if (row.type === 'vacancy') {
      // Calculate planned hours based on position work schedule
      const workingDays = days.filter(day => !day.isWeekend).length;
      const hoursPerShift = row.position?.hoursPerShift || 8;
      return workingDays * hoursPerShift;
    } else {
      return calculatePlannedHours(row.employee!);
    }
  };

  // Group-level totals for TimesheetRow arrays
  const getGroupTotalHours = (rows: TimesheetRow[]): number => {
    return rows.reduce((total, row) => total + getRowTotalHours(row), 0);
  };

  const getGroupPlannedHours = (rows: TimesheetRow[]): number => {
    return rows.reduce((total, row) => total + getRowPlannedHours(row), 0);
  };

  const isRowCellLocked = (row: TimesheetRow, date: string): boolean => {
    // If period is closed, all cells are locked
    if (isPeriodClosed) return true;

    // Vacancies are always locked
    if (row.type === 'vacancy') return true;

    // Normal lock logic for employees
    return isCellLocked(date, row.employee) || (row.employee ? isCellTerminated(row.employee, date) : false);
  };

  const handleCellChange = (employeeId: string, date: string, value: string | number, qualityScore?: number) => {
    const existingEntry = getTimeEntry(employeeId, date);

    // If empty value, delete entry
    if (value === "") {
      if (existingEntry?.id) {
        // Delete existing entry
        deleteTimeEntryMutation.mutate(existingEntry.id);
      }
      return;
    }

    const entryData = {
      id: existingEntry?.id,
      employeeId,
      date,
      hours: typeof value === "number" ? value : null,
      dayType: typeof value === "string" ? value.toUpperCase() : "work",
      qualityScore: qualityScore || 3,
    };

    updateTimeEntryMutation.mutate(entryData);
  };

  const deleteTimeEntryMutation = useMutation({
    mutationFn: async (id: string) => {
      return await apiRequest("DELETE", `/api/time-entries/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/time-entries", selectedMonth] });
    },
    onError: () => {
      toast({ title: "Ошибка при удалении данных", variant: "destructive" });
    },
  });

  const bulkDeleteMutation = useMutation({
    mutationFn: async (entryIds: string[]) => {
      await Promise.all(entryIds.map(id => apiRequest("DELETE", `/api/time-entries/${id}`)));
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/time-entries", selectedMonth] });
      toast({ title: "Данные успешно удалены" });
    },
    onError: () => {
      toast({ title: "Ошибка при удалении данных", variant: "destructive" });
    },
  });

  const bulkCreateMutation = useMutation({
    mutationFn: async (entries: any[]) => {
      await Promise.all(entries.map(entry => apiRequest("POST", "/api/time-entries", entry)));
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/time-entries", selectedMonth] });
      toast({ title: "Данные успешно заполнены" });
    },
    onError: () => {
      toast({ title: "Ошибка при заполнении данных", variant: "destructive" });
    },
  });



  // Clear all data for current month
  const handleClearAll = () => {
    const entriesToDelete = timeEntries
      .filter((entry: TimeEntry) => {
        const employee = employees.find(emp => emp.id === entry.employeeId);
        return !isCellLocked(entry.date, employee);
      })
      .map((entry: TimeEntry) => entry.id);

    if (entriesToDelete.length > 0) {
      bulkDeleteMutation.mutate(entriesToDelete);
    }
  };

  // Clear row data for specific employee
  const handleClearRow = (employeeId: string) => {
    const employee = employees.find(emp => emp.id === employeeId);
    const entriesToDelete = timeEntries
      .filter((entry: TimeEntry) => 
        entry.employeeId === employeeId && !isCellLocked(entry.date, employee)
      )
      .map((entry: TimeEntry) => entry.id);

    if (entriesToDelete.length > 0) {
      bulkDeleteMutation.mutate(entriesToDelete);
    }
  };

  // Fill row to end of month
  const handleFillToEnd = (employeeId: string, fromDate: string, sourceValue?: string | number, sourceQuality?: number) => {
    const employee = employees.find(emp => emp.id === employeeId);
    if (!employee || !sourceValue) return;

    const fromIndex = days.findIndex(day => day.date === fromDate);
    if (fromIndex === -1) return;

    const entriesToCreate = [];
    for (let i = fromIndex; i < days.length; i++) {
      const day = days[i];
      if (isCellLocked(day.date, employee) || isCellTerminated(employee, day.date)) continue;

      const existingEntry = getTimeEntry(employeeId, day.date);
      if (!existingEntry) {
        entriesToCreate.push({
          employeeId,
          date: day.date,
          hours: typeof sourceValue === "number" ? sourceValue : null,
          dayType: typeof sourceValue === "string" ? sourceValue.toUpperCase() : "work",
          qualityScore: sourceQuality || 3,
        });
      }
    }

    if (entriesToCreate.length > 0) {
      bulkCreateMutation.mutate(entriesToCreate);
    }
  };

  // Fill by employee schedule
  const handleFillBySchedule = (employeeId: string, sourceValue?: string | number, sourceQuality?: number) => {
    const employee = employees.find(emp => emp.id === employeeId);
    if (!employee || !sourceValue) return;

    const workSchedule = employee.workSchedule || "5/2";
    const entriesToCreate = [];

    if (workSchedule === "5/2") {
      // Fill weekdays only
      for (const day of days) {
        if (isCellLocked(day.date, employee) || isCellTerminated(employee, day.date) || day.isWeekend) continue;

        const existingEntry = getTimeEntry(employeeId, day.date);
        if (!existingEntry) {
          entriesToCreate.push({
            employeeId,
            date: day.date,
            hours: typeof sourceValue === "number" ? sourceValue : null,
            dayType: typeof sourceValue === "string" ? sourceValue.toUpperCase() : "work",
            qualityScore: sourceQuality || 3,
          });
        }
      }
    } else if (workSchedule === "2/2") {
      // 2/2 pattern: 2 work days, then 2 rest days
      let isWorkDay = true;
      let dayCount = 0;

      for (const day of days) {
        if (isCellLocked(day.date, employee) || isCellTerminated(employee, day.date)) continue;

        const existingEntry = getTimeEntry(employeeId, day.date);
        if (!existingEntry && dayCount < 2 && isWorkDay) {
          entriesToCreate.push({
            employeeId,
            date: day.date,
            hours: typeof sourceValue === "number" ? sourceValue : null,
            dayType: typeof sourceValue === "string" ? sourceValue.toUpperCase() : "work",
            qualityScore: sourceQuality || 3,
          });
        }

        dayCount++;
        if (dayCount === 2) {
          dayCount = 0;
          isWorkDay = !isWorkDay;
        }
      }
    } else if (workSchedule === "3/3") {
      // 3/3 pattern: 3 work days, then 3 rest days
      let isWorkDay = true;
      let dayCount = 0;

      for (const day of days) {
        if (isCellLocked(day.date, employee) || isCellTerminated(employee, day.date)) continue;

        const existingEntry = getTimeEntry(employeeId, day.date);
        if (!existingEntry && dayCount < 3 && isWorkDay) {
          entriesToCreate.push({
            employeeId,
            date: day.date,
            hours: typeof sourceValue === "number" ? sourceValue : null,
            dayType: typeof sourceValue === "string" ? sourceValue.toUpperCase() : "work",
            qualityScore: sourceQuality || 3,
          });
        }

        dayCount++;
        if (dayCount === 3) {
          dayCount = 0;
          isWorkDay = !isWorkDay;
        }
      }
    } else if (workSchedule === "6/1") {
      // 6/1 pattern: 6 work days, then 1 rest day
      let dayCount = 0;

      for (const day of days) {
        if (isCellLocked(day.date, employee) || isCellTerminated(employee, day.date)) continue;

        const existingEntry = getTimeEntry(employeeId, day.date);
        if (!existingEntry && dayCount < 6) {
          entriesToCreate.push({
            employeeId,
            date: day.date,
            hours: typeof sourceValue === "number" ? sourceValue : null,
            dayType: typeof sourceValue === "string" ? sourceValue.toUpperCase() : "work",
            qualityScore: sourceQuality || 3,
          });
        }

        dayCount++;
        if (dayCount === 7) {
          dayCount = 0;
        }
      }
    } else if (workSchedule === "вахта (7/0)") {
      // Вахта: все дни рабочие
      for (const day of days) {
        if (isCellLocked(day.date, employee) || isCellTerminated(employee, day.date)) continue;

        const existingEntry = getTimeEntry(employeeId, day.date);
        if (!existingEntry) {
          entriesToCreate.push({
            employeeId,
            date: day.date,
            hours: typeof sourceValue === "number" ? sourceValue : null,
            dayType: typeof sourceValue === "string" ? sourceValue.toUpperCase() : "work",
            qualityScore: sourceQuality || 3,
          });
        }
      }
    }

    if (entriesToCreate.length > 0) {
      bulkCreateMutation.mutate(entriesToCreate);
    }
  };

  const handleClosePeriod = () => {
    closePeriodMutation.mutate();
  };

  const handleReopenPeriod = () => {
    reopenPeriodMutation.mutate();
  };

  // Check if current month is in the past or present (not future)
  const canClosePeriod = useMemo(() => {
    const [year, month] = selectedMonth.split('-').map(Number);
    const selectedDate = new Date(year, month - 1);
    const today = new Date();
    const currentMonthStart = new Date(today.getFullYear(), today.getMonth());
    return selectedDate <= currentMonthStart;
  }, [selectedMonth]);

  const handleAutoFill = async () => {
    try {
      // Get previous month data (July 2025)
      const prevMonth = new Date(2025, 6, 1); // July 2025
      const prevMonthStr = `${prevMonth.getFullYear()}-${String(prevMonth.getMonth() + 1).padStart(2, '0')}`;

      // Fetch previous month entries
      const response = await fetch(`/api/time-entries?month=${prevMonthStr}`);
      const prevMonthEntries = await response.json();

      if (!prevMonthEntries || prevMonthEntries.length === 0) {
        toast({ 
          title: "Нет данных", 
          description: "Данные за предыдущий месяц не найдены",
          variant: "destructive"
        });
        return;
      }

      // Group previous month entries by employee
      const prevEntriesByEmployee = prevMonthEntries.reduce((acc: any, entry: any) => {
        if (!acc[entry.employeeId]) {
          acc[entry.employeeId] = [];
        }
        acc[entry.employeeId].push(entry);
        return acc;
      }, {});

      const entriesToCreate = [];

      // For each employee, analyze their pattern and extend it to current month
      for (const employee of employees) {
        const prevEntries = prevEntriesByEmployee[employee.id] || [];
        if (prevEntries.length === 0) continue;

        // Sort entries by date
        prevEntries.sort((a: any, b: any) => new Date(a.date).getTime() - new Date(b.date).getTime());

        // Detect pattern based on employee's work schedule
        const workSchedule = employee.workSchedule || "5/2";

        // Apply pattern based on employee's schedule
        if (workSchedule === "5/2") {
          // Fill weekdays only, using last working day pattern from previous month
          const lastWorkEntry = prevEntries.filter((entry: any) => entry.hours !== null).pop();
          if (lastWorkEntry) {
            for (const day of days) {
              if (isCellLocked(day.date, employee) || isCellTerminated(employee, day.date) || day.isWeekend) continue;

              const existingEntry = getTimeEntry(employee.id, day.date);
              if (!existingEntry) {
                entriesToCreate.push({
                  employeeId: employee.id,
                  date: day.date,
                  hours: lastWorkEntry.hours,
                  dayType: lastWorkEntry.dayType,
                  qualityScore: lastWorkEntry.qualityScore || 3,
                });
              }
            }
          }
        } else if (workSchedule === "2/2") {
          // 2/2 pattern: detect the last cycle and continue it
          const lastTwoWeeks = prevEntries.slice(-14);
          let isWorkDay = true;
          let dayCount = 0;

          // Find the pattern from the end of previous month
          if (lastTwoWeeks.length > 0) {
            const lastWorkEntry = lastTwoWeeks.filter((entry: any) => entry.hours !== null).pop();
            if (lastWorkEntry) {
              for (const day of days) {
                if (isCellLocked(day.date, employee) || isCellTerminated(employee, day.date)) continue;

                const existingEntry = getTimeEntry(employee.id, day.date);
                if (!existingEntry && dayCount < 2 && isWorkDay) {
                  entriesToCreate.push({
                    employeeId: employee.id,
                    date: day.date,
                    hours: lastWorkEntry.hours,
                    dayType: lastWorkEntry.dayType,
                    qualityScore: lastWorkEntry.qualityScore || 3,
                  });
                }

                dayCount++;
                if (dayCount === 2) {
                  dayCount = 0;
                  isWorkDay = !isWorkDay;
                }
              }
            }
          }
        } else if (workSchedule === "3/3") {
          // 3/3 pattern
          const lastWorkEntry = prevEntries.filter((entry: any) => entry.hours !== null).pop();
          if (lastWorkEntry) {
            let isWorkDay = true;
            let dayCount = 0;

            for (const day of days) {
              if (isCellLocked(day.date, employee) || isCellTerminated(employee, day.date)) continue;

              const existingEntry = getTimeEntry(employee.id, day.date);
              if (!existingEntry && dayCount < 3 && isWorkDay) {
                entriesToCreate.push({
                  employeeId: employee.id,
                  date: day.date,
                  hours: lastWorkEntry.hours,
                  dayType: lastWorkEntry.dayType,
                  qualityScore: lastWorkEntry.qualityScore || 3,
                });
              }

              dayCount++;
              if (dayCount === 3) {
                dayCount = 0;
                isWorkDay = !isWorkDay;
              }
            }
          }
        } else if (workSchedule === "6/1") {
          // 6/1 pattern
          const lastWorkEntry = prevEntries.filter((entry: any) => entry.hours !== null).pop();
          if (lastWorkEntry) {
            let dayCount = 0;

            for (const day of days) {
              if (isCellLocked(day.date, employee) || isCellTerminated(employee, day.date)) continue;

              const existingEntry = getTimeEntry(employee.id, day.date);
              if (!existingEntry && dayCount < 6) {
                entriesToCreate.push({
                  employeeId: employee.id,
                  date: day.date,
                  hours: lastWorkEntry.hours,
                  dayType: lastWorkEntry.dayType,
                  qualityScore: lastWorkEntry.qualityScore || 3,
                });
              }

              dayCount++;
              if (dayCount === 7) {
                dayCount = 0;
              }
            }
          }
        } else if (workSchedule === "вахта (7/0)") {
          // Вахта: all days are working days
          const lastWorkEntry = prevEntries.filter((entry: any) => entry.hours !== null).pop();
          if (lastWorkEntry) {
            for (const day of days) {
              if (isCellLocked(day.date, employee) || isCellTerminated(employee, day.date)) continue;

              const existingEntry = getTimeEntry(employee.id, day.date);
              if (!existingEntry) {
                entriesToCreate.push({
                  employeeId: employee.id,
                  date: day.date,
                  hours: lastWorkEntry.hours,
                  dayType: lastWorkEntry.dayType,
                  qualityScore: lastWorkEntry.qualityScore || 3,
                });
              }
            }
          }
        }
      }

      if (entriesToCreate.length > 0) {
        bulkCreateMutation.mutate(entriesToCreate);
        toast({ 
          title: "Автозаполнение выполнено", 
          description: `Заполнено ${entriesToCreate.length} записей на основе данных предыдущего месяца` 
        });
      } else {
        toast({ 
          title: "Нет данных для заполнения", 
          description: "Все ячейки уже заполнены или заблокированы" 
        });
      }
    } catch (error) {
      toast({ 
        title: "Ошибка автозаполнения", 
        description: "Не удалось получить данные предыдущего месяца",
        variant: "destructive"
      });
    }
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <Calendar className="h-8 w-8 text-primary" />
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-2xl font-bold">Табель учёта рабочего времени</h1>
              {isPeriodClosed && (
                <Badge variant="secondary" className="bg-gray-200 dark:bg-gray-700">
                  <Lock className="w-3 h-3 mr-1" />
                  Период закрыт
                </Badge>
              )}
              {isReportApproved && (
                <Badge variant="default" className="bg-green-600">
                  Отчёт утверждён
                </Badge>
              )}
            </div>
            <p className="text-muted-foreground">Учёт рабочих часов и оценка качества работы</p>
          </div>
        </div>

        <div className="flex items-center space-x-4">
          <Button 
            onClick={handleClearAll} 
            variant="destructive" 
            size="sm"
            disabled={bulkDeleteMutation.isPending || isPeriodClosed}
            data-testid="button-clear-all"
          >
            Очистить всё
          </Button>

          <Button 
            onClick={handleAutoFill} 
            variant="outline" 
            size="sm"
            disabled={isPeriodClosed}
          >
            <Wand2 className="w-4 h-4 mr-2" />
            Автозаполнение
          </Button>

          {!isPeriodClosed ? (
            <Button 
              onClick={handleClosePeriod} 
              className="bg-orange-600 hover:bg-orange-700"
              size="sm"
              disabled={!canClosePeriod || closePeriodMutation.isPending}
              data-testid="button-close-period"
            >
              <Lock className="w-4 h-4 mr-2" />
              Закрыть период
            </Button>
          ) : (
            <Button 
              onClick={handleReopenPeriod} 
              variant="outline"
              size="sm"
              disabled={isReportApproved || reopenPeriodMutation.isPending}
              data-testid="button-reopen-period"
            >
              <LockOpen className="w-4 h-4 mr-2" />
              Открыть период
            </Button>
          )}

          <Select value={selectedMonth} onValueChange={setSelectedMonth}>
            <SelectTrigger className="w-[180px]">
              <SelectValue placeholder="Выберите месяц" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="2025-06">Июнь 2025</SelectItem>
              <SelectItem value="2025-07">Июль 2025</SelectItem>
              <SelectItem value="2025-08">Август 2025</SelectItem>
              <SelectItem value="2025-09">Сентябрь 2025</SelectItem>
              <SelectItem value="2025-10">Октябрь 2025</SelectItem>
              <SelectItem value="2025-11">Ноябрь 2025</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      {/* Timesheet Table */}
      <div className="border rounded-lg bg-background">
        <table className="w-full border-collapse text-[10px]">
            {/* Header */}
            <thead>
              <tr>
                <th className="sticky left-0 z-20 bg-background border-r border-b p-1 text-left w-36">
                  <div className="text-[9px] font-medium truncate">Должность</div>
                </th>
                <th className="sticky left-36 z-20 bg-background border-r border-b p-1 text-left w-40">
                  <div className="text-[9px] font-medium truncate">ФИО сотрудника</div>
                </th>
                {days.map((day) => (
                  <th 
                    key={day.day}
                    className={`border-b border-r p-0.5 text-center w-6 ${
                      day.isWeekend ? 'bg-red-50 dark:bg-red-950/20' : 'bg-gray-50 dark:bg-gray-950/50'
                    }`}
                  >
                    <div className="text-[7px] font-medium">{day.dayOfWeek.slice(0,2)}</div>
                    <div className="text-[8px] font-bold">{day.day}</div>
                  </th>
                ))}
                <th className="border-b p-1 text-center bg-primary/5 w-10">
                  <div className="text-[7px]">Итого</div>
                  <div className="text-[8px] font-bold">час</div>
                </th>
                <th className="border-b p-1 text-center bg-green-50 dark:bg-green-950/20 w-10">
                  <div className="text-[7px]">План</div>
                  <div className="text-[8px] font-bold">час</div>
                </th>
              </tr>
            </thead>

            {/* Body - Active Employees Section */}
            <tbody>
              {/* Active Employees Header */}
              {activeEmployeeRows.length > 0 && (
                <tr className="bg-blue-50 dark:bg-blue-950/20">
                  <td colSpan={days.length + 4} className="p-2 font-semibold text-sm text-blue-800 dark:text-blue-200">
                    Штатные сотрудники
                  </td>
                </tr>
              )}

              {/* Active Employees Rows */}
              {activeEmployeeRows.map((row) => {
                const totalHours = getRowTotalHours(row);
                const plannedHours = getRowPlannedHours(row);
                const insufficientHours = row.type === 'employee' ? hasInsufficientHours(row.employee!, totalHours) : false;
                const isVacancy = row.type === 'vacancy';

                return (
                  <tr 
                    key={row.id} 
                    className={`hover:bg-muted/30 ${row.employee?.status === "fired" ? "opacity-75" : ""} ${
                      insufficientHours ? "border-b-2 border-red-500" : ""
                    } ${isVacancy ? "bg-gray-50 dark:bg-gray-900/20" : ""}`}
                  >
                    <td className="sticky left-0 z-20 bg-background border-r p-1 font-medium">
                      <div className={`text-[9px] truncate ${
                        insufficientHours ? "text-red-500 font-semibold" : "text-muted-foreground"
                      } ${isVacancy ? "text-orange-500" : ""}`} title={row.positionTitle}>
                        {row.positionTitle}
                      </div>
                    </td>
                    <td className="sticky left-36 z-20 bg-background border-r p-1 font-medium">
                      <div className={`text-[9px] truncate ${
                        insufficientHours ? "text-red-600 font-bold" : ""
                      } ${isVacancy ? "text-orange-600 font-semibold" : ""}`} title={row.name}>
                        {row.name}{row.employee?.status === "fired" ? " (уволен)" : ""}
                      </div>
                    </td>
                    {days.map((day) => {
                      const entry = row.type === 'employee' ? getTimeEntry(row.id, day.date) : null;
                      const isRowLocked = isRowCellLocked(row, day.date);

                      return (
                        <td key={day.date} className="p-0">
                          <TimesheetCell
                            value={entry?.hours !== null ? entry?.hours : entry?.dayType}
                            qualityScore={entry?.qualityScore || 3}
                            isLocked={isRowLocked}
                            isTerminated={row.type === 'employee' ? isCellTerminated(row.employee!, day.date) : false}
                            employeeId={row.type === 'employee' ? row.id : ''}
                            date={day.date}
                            isPartTime={false}
                            onChange={(value, qualityScore) => {
                              if (row.type === 'employee') {
                                handleCellChange(row.id, day.date, value, qualityScore);
                              }
                            }}
                            onClearRow={() => {
                              if (row.type === 'employee') {
                                handleClearRow(row.id);
                              }
                            }}
                            onFillBySchedule={() => {
                              if (row.type === 'employee' && entry) {
                                handleFillBySchedule(row.id, entry?.hours !== null ? entry?.hours : entry?.dayType, entry?.qualityScore || undefined);
                              }
                            }}
                          />
                        </td>
                      );
                    })}
                    <td className="border-r p-1 text-center font-bold bg-primary/5">
                      <div className="text-[9px]">{totalHours}</div>
                    </td>
                    <td className="border-r p-1 text-center font-bold bg-green-50 dark:bg-green-950/20">
                      <div className="text-[9px]">{plannedHours}</div>
                    </td>
                  </tr>
                );
              })}

              {/* Active Employees Subtotal */}
              {activeEmployeeRows.length > 0 && (
                <tr className="bg-blue-100 dark:bg-blue-900/30 border-t-2 border-blue-300">
                  <td colSpan={2} className="sticky left-0 z-10 bg-blue-100 dark:bg-blue-900/30 border-r p-1 font-bold text-blue-800 dark:text-blue-200">
                    <div className="text-[10px]">Итого активные: {activeEmployeeRows.length} чел.</div>
                  </td>
                  {days.map((day) => (
                    <td key={day.date} className="p-0 bg-blue-100 dark:bg-blue-900/30"></td>
                  ))}
                  <td className="border-r p-1 text-center font-bold bg-blue-200 dark:bg-blue-800/50 text-blue-800 dark:text-blue-200">
                    <div className="text-[10px]">{getGroupTotalHours(activeEmployeeRows)}</div>
                  </td>
                  <td className="border-r p-1 text-center font-bold bg-green-100 dark:bg-green-800/50 text-green-800 dark:text-green-200">
                    <div className="text-[10px]">{getGroupPlannedHours(activeEmployeeRows)}</div>
                  </td>
                </tr>
              )}

              {/* Part-time Employees Header */}
              {partTimeEmployees.length > 0 && (
                <tr className="bg-orange-50 dark:bg-orange-950/20">
                  <td colSpan={days.length + 4} className="p-2 font-semibold text-sm text-orange-800 dark:text-orange-200">
                    Подработка
                  </td>
                </tr>
              )}

              {/* Part-time Employees Rows */}
              {partTimeEmployees.map((employee) => {
                const totalHours = timeEntries
                  .filter((entry: TimeEntry) => entry.employeeId === employee.id && typeof entry.hours === 'number')
                  .reduce((sum: number, entry: TimeEntry) => sum + (entry.hours || 0), 0);

                const insufficientHours = hasInsufficientHours(employee, totalHours);

                return (
                  <tr 
                    key={employee.id} 
                    className={`hover:bg-muted/30 ${employee.status === "fired" ? "opacity-75" : ""} ${
                      insufficientHours ? "border-b-2 border-red-500" : ""
                    }`}
                  >
                    <td className="sticky left-0 z-20 bg-background border-r p-1 font-medium">
                      <div className={`text-[9px] truncate text-muted-foreground`} title={employee.position}>
                        {employee.position}
                      </div>
                    </td>
                    <td className="sticky left-36 z-20 bg-background border-r p-1 font-medium">
                      <div className={`text-[9px] truncate ${
                        insufficientHours ? "text-red-600 font-bold" : ""
                      }`} title={employee.name}>
                        {employee.name}{employee.status === "fired" ? " (уволен)" : ""}
                      </div>
                    </td>
                    {days.map((day) => {
                      const entry = getTimeEntry(employee.id, day.date);
                      const isTerminated = isCellTerminated(employee, day.date);
                      const isLocked = isCellLocked(day.date, employee);

                      return (
                        <td key={day.date} className="p-0">
                          <TimesheetCell
                            value={entry?.hours !== null ? entry?.hours : entry?.dayType}
                            qualityScore={entry?.qualityScore || 3}
                            isLocked={isLocked}
                            isTerminated={isTerminated}
                            employeeId={employee.id}
                            date={day.date}
                            isPartTime={true}
                            onChange={(value, qualityScore) => 
                              handleCellChange(employee.id, day.date, value, qualityScore)
                            }
                            onClearRow={() => handleClearRow(employee.id)}
                            onFillBySchedule={() => handleFillBySchedule(employee.id, entry?.hours !== null ? entry?.hours : entry?.dayType, entry?.qualityScore || undefined)}
                          />
                        </td>
                      );
                    })}
                    <td className="border-r p-1 text-center font-bold bg-primary/5">
                      <div className="text-[9px]">{totalHours}</div>
                    </td>
                    <td className="border-r p-1 text-center font-bold bg-green-50 dark:bg-green-950/20">
                      <div className="text-[9px]">{calculatePlannedHours(employee)}</div>
                    </td>
                  </tr>
                );
              })}

              {/* Part-time Employees Subtotal */}
              {partTimeEmployees.length > 0 && (
                <tr className="bg-orange-100 dark:bg-orange-900/30 border-t-2 border-orange-300">
                  <td colSpan={2} className="sticky left-0 z-10 bg-orange-100 dark:bg-orange-900/30 border-r p-1 font-bold text-orange-800 dark:text-orange-200">
                    <div className="text-[10px]">Итого подработка: {partTimeEmployees.length} чел.</div>
                  </td>
                  {days.map((day) => (
                    <td key={day.date} className="p-0 bg-orange-100 dark:bg-orange-900/30"></td>
                  ))}
                  <td className="border-r p-1 text-center font-bold bg-orange-200 dark:bg-orange-800/50 text-orange-800 dark:text-orange-200">
                    <div className="text-[10px]">{getGroupTotalHours(partTimeEmployeeRows)}</div>
                  </td>
                  <td className="border-r p-1 text-center font-bold bg-green-100 dark:bg-green-800/50 text-green-800 dark:text-green-200">
                    <div className="text-[10px]">{getGroupPlannedHours(partTimeEmployeeRows)}</div>
                  </td>
                </tr>
              )}

              {/* Vacancies Header */}
              {vacancyRows.length > 0 && (
                <tr 
                  className="bg-gray-50 dark:bg-gray-950/20 cursor-pointer hover:bg-gray-100 dark:hover:bg-gray-900/40"
                  onClick={() => setVacanciesExpanded(!vacanciesExpanded)}
                >
                  <td colSpan={days.length + 4} className="p-2 font-semibold text-sm text-gray-700 dark:text-gray-300">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <span>Вакансии</span>
                        <span className="text-xs font-normal text-muted-foreground">
                          ({vacancyRows.length} {vacancyRows.length === 1 ? 'вакансия' : vacancyRows.length < 5 ? 'вакансии' : 'вакансий'})
                        </span>
                      </div>
                      {vacanciesExpanded ? (
                        <ChevronDown className="w-4 h-4" />
                      ) : (
                        <ChevronRight className="w-4 h-4" />
                      )}
                    </div>
                  </td>
                </tr>
              )}

              {/* Vacancies Rows */}
              {vacanciesExpanded && vacancyRows.map((row) => {
                const totalHours = getRowTotalHours(row);
                const plannedHours = getRowPlannedHours(row);

                return (
                  <tr 
                    key={row.id} 
                    className="hover:bg-muted/30 bg-gray-50 dark:bg-gray-900/20"
                  >
                    <td className="sticky left-0 z-20 bg-background border-r p-1 font-medium">
                      <div className="text-[9px] truncate text-orange-500" title={row.positionTitle}>
                        {row.positionTitle}
                      </div>
                    </td>
                    <td className="sticky left-36 z-20 bg-background border-r p-1 font-medium">
                      <div className="text-[9px] truncate text-orange-600 font-semibold" title={row.name}>
                        {row.name}
                      </div>
                    </td>
                    {days.map((day) => {
                      return (
                        <td key={day.date} className="p-0">
                          <TimesheetCell
                            value=""
                            qualityScore={3}
                            isLocked={true}
                            isTerminated={false}
                            employeeId=""
                            date={day.date}
                            isPartTime={false}
                            onChange={() => {}}
                          />
                        </td>
                      );
                    })}
                    <td className="border-r p-1 text-center font-bold bg-primary/5">
                      <div className="text-[9px]">{totalHours}</div>
                    </td>
                    <td className="border-r p-1 text-center font-bold bg-green-50 dark:bg-green-950/20">
                      <div className="text-[9px]">{plannedHours}</div>
                    </td>
                  </tr>
                );
              })}

              {/* Vacancies Subtotal */}
              {vacanciesExpanded && vacancyRows.length > 0 && (
                <tr className="bg-gray-100 dark:bg-gray-900/30 border-t-2 border-gray-300">
                  <td colSpan={2} className="sticky left-0 z-10 bg-gray-100 dark:bg-gray-900/30 border-r p-1 font-bold text-gray-800 dark:text-gray-200">
                    <div className="text-[10px]">Итого вакансии: {vacancyRows.length} шт.</div>
                  </td>
                  {days.map((day) => (
                    <td key={day.date} className="p-0 bg-gray-100 dark:bg-gray-900/30"></td>
                  ))}
                  <td className="border-r p-1 text-center font-bold bg-gray-200 dark:bg-gray-800/50 text-gray-800 dark:text-gray-200">
                    <div className="text-[10px]">{getGroupTotalHours(vacancyRows)}</div>
                  </td>
                  <td className="border-r p-1 text-center font-bold bg-green-100 dark:bg-green-800/50 text-green-800 dark:text-green-200">
                    <div className="text-[10px]">{getGroupPlannedHours(vacancyRows)}</div>
                  </td>
                </tr>
              )}

              {/* Overall Total Row */}
              <tr className="bg-gray-200 dark:bg-gray-800 border-t-4 border-gray-400">
                <td colSpan={2} className="sticky left-0 z-10 bg-gray-200 dark:bg-gray-800 border-r p-1 font-bold text-gray-800 dark:text-gray-200">
                  <div className="text-[11px]">ОБЩИЙ ИТОГ:</div>
                </td>
                {days.map((day) => (
                  <td key={day.date} className="p-0 bg-gray-200 dark:bg-gray-800"></td>
                ))}
                <td className="border-r p-1 text-center font-bold bg-gray-300 dark:bg-gray-700 text-gray-800 dark:text-gray-200">
                  <div className="text-[11px]">{getGroupTotalHours([...activeEmployeeRows, ...partTimeEmployeeRows, ...vacancyRows])}</div>
                </td>
                <td className="border-r p-1 text-center font-bold bg-green-200 dark:bg-green-700 text-green-800 dark:text-green-200">
                  <div className="text-[11px]">{getGroupPlannedHours([...activeEmployeeRows, ...partTimeEmployeeRows, ...vacancyRows])}</div>
                </td>
              </tr>
            </tbody>
        </table>
      </div>

      {/* Legend - Three Rows */}
      <div className="bg-muted/30 rounded-lg p-3 text-xs space-y-2">
        {/* Row 1: Обозначения */}
        <div className="flex items-center gap-2">
          <span className="font-semibold">Обозначения:</span>
          <div className="flex items-center space-x-1.5">
            <div className="w-5 h-5 bg-blue-100 dark:bg-blue-900/30 border rounded text-center text-blue-800 dark:text-blue-200 text-[10px] font-bold flex items-center justify-center">Б</div>
            <span className="text-[11px]">Больничный</span>
          </div>
          <div className="flex items-center space-x-1.5">
            <div className="w-5 h-5 bg-purple-100 dark:bg-purple-900/30 border rounded text-center text-purple-800 dark:text-purple-200 text-[10px] font-bold flex items-center justify-center">О</div>
            <span className="text-[11px]">Отпуск</span>
          </div>
          <div className="flex items-center space-x-1.5">
            <div className="w-5 h-5 bg-gray-200 dark:bg-gray-700 border rounded text-center text-gray-700 dark:text-gray-300 text-[10px] font-bold flex items-center justify-center">НН</div>
            <span className="text-[11px]">Прогул</span>
          </div>
          <div className="flex items-center space-x-1.5">
            <div className="w-5 h-5 bg-red-100 dark:bg-red-900/30 border rounded text-center text-red-800 dark:text-red-200 text-[10px] font-bold flex items-center justify-center">У</div>
            <span className="text-[11px]">Уволен</span>
          </div>
        </div>

        {/* Row 2: Оценки */}
        <div className="flex items-center gap-2">
          <span className="font-semibold">Оценки:</span>
          <div className="flex items-center space-x-1.5">
            <div className="w-5 h-5 bg-red-100 dark:bg-red-900/30 border rounded text-center text-red-800 dark:text-red-200 text-[10px] font-bold flex items-center justify-center">1</div>
            <span className="text-[11px]">Плохо</span>
          </div>
          <div className="flex items-center space-x-1.5">
            <div className="w-5 h-5 bg-orange-100 dark:bg-orange-900/30 border rounded text-center text-orange-800 dark:text-orange-200 text-[10px] font-bold flex items-center justify-center">2</div>
            <span className="text-[11px]">Удовлетв.</span>
          </div>
          <div className="flex items-center space-x-1.5">
            <div className="w-5 h-5 bg-yellow-100 dark:bg-yellow-900/30 border rounded text-center text-yellow-800 dark:text-yellow-200 text-[10px] font-bold flex items-center justify-center">3</div>
            <span className="text-[11px]">Хорошо</span>
          </div>
          <div className="flex items-center space-x-1.5">
            <div className="w-5 h-5 bg-green-100 dark:bg-green-900/30 border rounded text-center text-green-800 dark:text-green-200 text-[10px] font-bold flex items-center justify-center">4</div>
            <span className="text-[11px]">Отлично</span>
          </div>
        </div>

        {/* Row 3: Подсказки */}
        <div className="flex items-center gap-3 text-[10px] text-muted-foreground">
          <div>• 1-24 — часы</div>
          <div>• Пр. кн. мыши — оценка</div>
          <div>• Enter — сохранить</div>
        </div>
      </div>
    </div>
  );
}

