import { 
  type User, 
  type InsertUser,
  type Employee,
  type InsertEmployee,
  type TimeEntry,
  type InsertTimeEntry,
  type Report,
  type InsertReport,
  type Setting,
  type InsertSetting,
  type Object,
  type InsertObject,
  type Position,
  type InsertPosition,
  type TimesheetPeriod,
  type InsertTimesheetPeriod,
  users,
  employees,
  timeEntries,
  reports,
  settings,
  objects,
  positions,
  timesheetPeriods
} from "@shared/schema";
import { randomUUID } from "crypto";
import { drizzle } from "drizzle-orm/neon-http";
import { neon } from "@neondatabase/serverless";
import { eq, and } from "drizzle-orm";

export interface IStorage {
  // Users
  getUser(id: string): Promise<User | undefined>;
  getUserByUsername(username: string): Promise<User | undefined>;
  createUser(user: InsertUser): Promise<User>;
  getUsers(): Promise<User[]>;
  updateUser(id: string, updateData: Partial<InsertUser>): Promise<User | undefined>;

  // Employees
  getEmployees(): Promise<Employee[]>;
  getEmployee(id: string): Promise<Employee | undefined>;
  createEmployee(employee: InsertEmployee): Promise<Employee>;
  updateEmployee(id: string, employee: Partial<InsertEmployee>): Promise<Employee | undefined>;
  deleteEmployee(id: string): Promise<boolean>;

  // Time Entries
  getTimeEntries(employeeId?: string, startDate?: string, endDate?: string): Promise<TimeEntry[]>;
  createTimeEntry(entry: InsertTimeEntry): Promise<TimeEntry>;
  updateTimeEntry(id: string, entry: Partial<InsertTimeEntry>): Promise<TimeEntry | undefined>;
  deleteTimeEntry(id: string): Promise<boolean>;

  // Reports
  getReports(): Promise<Report[]>;
  getReport(id: string): Promise<Report | undefined>;
  createReport(report: InsertReport): Promise<Report>;
  updateReport(id: string, report: Partial<InsertReport>): Promise<Report | undefined>;

  // Settings
  getSettings(): Promise<Setting[]>;
  getSetting(key: string): Promise<Setting | undefined>;
  setSetting(setting: InsertSetting): Promise<Setting>;

  // Objects
  getObjects(): Promise<Object[]>;
  getObject(id: string): Promise<Object | undefined>;
  createObject(object: InsertObject): Promise<Object>;
  updateObject(id: string, object: Partial<InsertObject>): Promise<Object | undefined>;
  deleteObject(id: string): Promise<boolean>;

  // Positions
  getPositions(objectId?: string): Promise<Position[]>;
  getPosition(id: string): Promise<Position | undefined>;
  createPosition(position: InsertPosition): Promise<Position>;
  updatePosition(id: string, position: Partial<InsertPosition>): Promise<Position | undefined>;
  deletePosition(id: string): Promise<boolean>;

  // Timesheet Periods
  getTimesheetPeriod(objectId: string, period: string): Promise<TimesheetPeriod | undefined>;
  getTimesheetPeriodById(id: string): Promise<TimesheetPeriod | undefined>;
  createTimesheetPeriod(timesheetPeriod: InsertTimesheetPeriod): Promise<TimesheetPeriod>;
  updateTimesheetPeriod(id: string, timesheetPeriod: Partial<InsertTimesheetPeriod>): Promise<TimesheetPeriod | undefined>;
}

export class MemStorage implements IStorage {
  private users: Map<string, User>;
  private employees: Map<string, Employee>;
  private timeEntries: Map<string, TimeEntry>;
  private reports: Map<string, Report>;
  private settings: Map<string, Setting>;
  private objects: Map<string, Object>;
  private positions: Map<string, Position>;
  private timesheetPeriods: Map<string, TimesheetPeriod>;

  constructor() {
    this.users = new Map();
    this.employees = new Map();
    this.timeEntries = new Map();
    this.reports = new Map();
    this.settings = new Map();
    this.objects = new Map();
    this.positions = new Map();
    this.timesheetPeriods = new Map();

    // Initialize with demo data
